                  }
                ]
              },
              {
                "TOCHeading": "Hazard Classes and Categories",
                "Description": "The Hazard Classes and Categories are aligned with GHS (Globally Harmonized System of Classification and Labelling of Chemicals) hazard statement codes.  The percentage data in the parenthesis from ECHA indicates that the hazard classes and categories information are consolidated from multiple companies.  Also, see the detailed explanation from the above GHS classification section.",
                "URL": "https://pubchem.ncbi.nlm.nih.gov/ghs/",
                "DisplayControls": {
                  "ShowAtMost": 1
                },
                "Information": [
                  {
                    "ReferenceNumber": 44,
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "Not Classified"
                        }
                      ]
                    }
                  }
                ]
              },
              {
                "TOCHeading": "EPA Safer Chemical",
                "Description": "EPA labels products so that consumers can easily choose ones that are safer for people and the environment. When consumers see the Safer Choice label on a product, they can be confident that the ingredients have been through a rigorous EPA review. The label means that EPA scientists have evaluated every ingredient in the product to ensure it meets Safer Choice's stringent criteria. When people use Safer Choice products, they are protecting their families and the environment by making safer chemical choices.",
                "URL": "https://www.epa.gov/saferchoice/safer-ingredients",
                "Information": [
                  {
                    "ReferenceNumber": 39,
                    "Name": "EPA Safer Chemical",
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "Chemical: DL-Methionine"
                        },
                        {
                          "String": " Green circle - The chemical has been verified to be of low concern based on experimental and modeled data.",
                          "Markup": [
                            {
                              "Start": 0,
                              "Length": 1,
                              "URL": "https://pubchem.ncbi.nlm.nih.gov/images/epasafe/green.svg",
                              "Type": "Icon",
                              "Extra": "Green circle"
                            }
                          ]
                        }
                      ]
                    }
                  },
                  {
                    "ReferenceNumber": 40,
                    "Name": "EPA Safer Chemical",
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "Chemical: L-Methionine"
                        },
                        {
                          "String": " Green half-circle - The chemical is expected to be of low concern based on experimental and modeled data. Additional data would strengthen EPA's confidence in the chemical's safer status.",
                          "Markup": [
                            {
                              "Start": 0,
                              "Length": 1,
                              "URL": "https://pubchem.ncbi.nlm.nih.gov/images/epasafe/half.svg",
                              "Type": "Icon",
                              "Extra": "Green half-circle"
                            }
                          ]
                        }
                      ]
                    }
                  }
                ]
              },
              {
                "TOCHeading": "Health Hazards",
                "Description": "Description of the chemical's health hazards (e.g., toxicity, corrosivity, and flammability) that can have negative impacts on our short- or long-term health.",
                "Information": [
                  {
                    "ReferenceNumber": 5,
                    "Reference": [
                      "National Toxicology Program, Institute of Environmental Health Sciences, National Institutes of Health (NTP). 1992. National Toxicology Program Chemical Repository Database. Research Triangle Park, North Carolina."
                    ],
                    "ExtendedReference": [
                      {
                        "Citation": "National Toxicology Program, Institute of Environmental Health Sciences, National Institutes of Health (NTP). 1992. National Toxicology Program Chemical Repository Database. Research Triangle Park, North Carolina.",
                        "Matched": {
                          "PCLID": 900163266,
                          "Citation": "National Toxicology Program, Institute of Environmental Health Sciences, National Institutes of Health (NTP). 1992. National Toxicology Program Chemical Repository Database. Research Triangle Park, North Carolina."
                        }
                      }
                    ],
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "ACUTE/CHRONIC HAZARDS: This material is dangerous when heated to decomposition; it emits dangerous and highly toxic fumes. (NTP, 1992)"
                        }
                      ]
                    }
                  }
                ]
              },
              {
                "TOCHeading": "Fire Hazards",
                "Description": "Fire hazard means any situation, process, material or condition which may cause a fire or explosion or provide a ready fuel supply to increase the spread or intensity of the fire or explosion and which poses a threat to life or property.  This section provides information on fire hazards involving this chemical.",
                "Information": [
                  {
                    "ReferenceNumber": 5,
                    "Reference": [
                      "National Toxicology Program, Institute of Environmental Health Sciences, National Institutes of Health (NTP). 1992. National Toxicology Program Chemical Repository Database. Research Triangle Park, North Carolina."
                    ],
                    "ExtendedReference": [
                      {
                        "Citation": "National Toxicology Program, Institute of Environmental Health Sciences, National Institutes of Health (NTP). 1992. National Toxicology Program Chemical Repository Database. Research Triangle Park, North Carolina.",
                        "Matched": {
                          "PCLID": 900163266,
                          "Citation": "National Toxicology Program, Institute of Environmental Health Sciences, National Institutes of Health (NTP). 1992. National Toxicology Program Chemical Repository Database. Research Triangle Park, North Carolina."
                        }
                      }
                    ],
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "Flash point data for this material is not available, but it is probably combustible. (NTP, 1992)"
                        }
                      ]
                    }
                  }
                ]
              },
              {
                "TOCHeading": "Hazards Summary",
                "Description": "This section provides an overview of the key hazards information of this compound.",
                "Information": [
                  {
                    "ReferenceNumber": 52,
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "Reacts with water evolving hydrogen sulfide (toxic and flammable); [CAMEO] May cause irritation; [Sigma-Aldrich MSDS] See Hydrogen sulfide.",
                          "Markup": [
                            {
                              "Start": 12,
                              "Length": 5,
                              "URL": "https://pubchem.ncbi.nlm.nih.gov/compound/water",
                              "Type": "PubChem Internal Link",
                              "Extra": "CID-962"
                            },
                            {
                              "Start": 27,
                              "Length": 16,
                              "URL": "https://pubchem.ncbi.nlm.nih.gov/compound/hydrogen%20sulfide",
                              "Type": "PubChem Internal Link",
